  {id: 2, name: 'Мобильное приложение', description: 'Всё важное — всегда под рукой', category: 'Разработка', color: 'peach', progress: 42, tasks: 32, done: 13, date: '24 ноября', status: 'В работе', members: ['ДВ', 'ЕЛ', 'АК']},
  {id: 3, name: 'Бренд-платформа', description: 'Находим свой голос и характер', category: 'Маркетинг', color: 'green', progress: 85, tasks: 18, done: 15, date: '8 ноября', status: 'На проверке', members: ['МС', 'ЕЛ']},
];
const initialTasks = [
  {id: 1, title: 'Согласовать концепцию главной страницы', project: 'Редизайн сайта', color: 'violet', time: 'Сегодня', done: false},
  {id: 2, title: 'Подготовить прототип онбординга', project: 'Мобильное приложение', color: 'peach', time: 'Сегодня', done: false},
  {id: 3, title: 'Собрать референсы для айдентики', project: 'Бренд-платформа', color: 'green', time: 'Сегодня', done: true},
];
const pageNames = {overview: 'Обзор', projects: 'Проекты', settings: 'Настройки'};
function readStored<T,>(key: string, fallback: T): T {try {const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback;} catch {return fallback;}}
function getPage(): Page {const value = window.location.hash.slice(1); return value === 'projects' || value === 'settings' ? value : 'overview';}
const BrandMark = () => <svg width=\"30\" height=\"30\" viewBox=\"0 0 30 30\" fill=\"none\" aria-hidden=\"true\"><path d=\"M6 9.5 15 4l9 5.5-9 5.5-9-5.5Z\" fill=\"currentColor\"/><path d=\"m6 15 9 5.5 9-5.5M6 20.5l9 5.5 9-5.5\" stroke=\"currentColor\" strokeWidth=\"3\" strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>;
function Avatars({members}: {members: string[]}) {return <div className=\"avatars\">{members.map((m, i) => <span key={m} className={"'`avatar avatar-${i}`} title={{АК: '"'Александр Ковалёв', МС: 'Мария Смирнова', ДВ: 'Дмитрий Волков', ЕЛ: 'Елена Лебедева'}[m]}>{m}</span>)}<span className=\"avatar avatar-more\">+{members.length === 2 ? 1 : 2}</span></div>;}

export function App() {
  const [theme, setTheme] = useState<Theme>(() => readStored('potok-theme', 'light'));
  const [page, setPage] = useState<Page>(getPage);
  const [narrow, setNarrow] = useState(() => window.innerWidth < 760);
  const [projects, setProjects] = useState<Project[]>(() => readStored('potok-projects', initialProjects));
  const [tasks, setTasks] = useState(() => readStored('potok-tasks', initialTasks));
  const [search, setSearch] = useState('');
