    <div className="project-card-footer"><Avatars members={p.members}/><Button view="flat" size="s" aria-label={`Открыть ${p.name}`} onClick={() => setSelectedProject(p)}><Icon data={ArrowUpRight} size={17}/></Button></div>
  </article>;}

  const renderOverview = () => <>
    <div className="page-heading"><div><div className="eyebrow">ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО</div><Text as="h1" variant="display-2">Обзор</Text><p>Большие идеи начинаются с маленьких шагов.</p></div><Button size="l" view="action" onClick={openNew}><Icon data={Plus} size={17}/> Создать проект</Button></div>
    <section className="welcome-banner"><div className="welcome-copy"><span className="welcome-tag"><span className="sun-dot"/> ХОРОШИЙ ДЕНЬ ДЛЯ НОВЫХ ИДЕЙ</span><Text as="h2" variant="display-2">Меньше суеты.<br/>Больше потока.</Text><p>Все проекты, задачи и команда — в одном месте.<br className="desktop-break"/> Сосредоточьтесь на том, что действительно важно.</p><Button view="normal" size="l" className="hero-button" onClick={() => navigate('"'projects')}>Перейти к проектам <Icon data={ArrowRight} size={17}/></Button></div>
