/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root {
  --g-font-family-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-border-radius-xs: 4px;
  --g-border-radius-s: 6px;
  --g-border-radius-m: 8px;
  --g-border-radius-l: 12px;
  --g-border-radius-xl: 16px;
}
.g-root_theme_light {
  --g-color-base-brand: #307b5b;
  --g-color-base-brand-hover: #256548;
  --g-color-base-selection: #e1f1e9;
  --g-color-base-selection-hover: #d3e9de;
  --g-color-line-brand: #307b5b;
  --g-color-text-brand: #307b5b;
  --g-color-text-brand-heavy: #20563e;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #307b5b;
  --g-color-text-link-hover: #256548;
  --g-color-text-link-visited: #307b5b;
  --g-color-text-link-visited-hover: #256548;
  --g-color-line-focus: #307b5b;
  --g-color-text-primary: #252d2a;
  --g-color-text-secondary: #818783;
  --g-color-text-complementary: #69716c;
  --g-color-base-generic-ultralight: #f8f9f7;
  --g-color-line-generic: #e9ece9;
}
.g-root_theme_dark {
  --g-color-base-brand: #83c6a5;
  --g-color-base-brand-hover: #a0d7bc;
  --g-color-base-selection: #253b30;
  --g-color-base-selection-hover: #2e493a;
  --g-color-line-brand: #83c6a5;
  --g-color-text-brand: #83c6a5;
  --g-color-text-brand-heavy: #c2e7d0;
  --g-color-text-brand-contrast: #17291f;
  --g-color-text-link: #83c6a5;
  --g-color-text-link-hover: #a0d7bc;
  --g-color-text-link-visited: #83c6a5;
  --g-color-text-link-visited-hover: #a0d7bc;
  --g-color-line-focus: #83c6a5;
  --g-color-base-background: #1b201d;
  --g-color-base-generic-ultralight: #191e1b;
  --g-color-text-primary: #e5eae6;
  --g-color-text-secondary: #929c95;
  --g-color-text-complementary: #b1b9b3;
  --g-color-line-generic: #303932;
}
* {box-sizing: border-box;}
body {margin: 0; -webkit-font-smoothing: antialiased;}
button, input {font: inherit;}
button {touch-action: manipulation;}
p {line-height: 1.65;}
h1, h2, h3, p {margin-top: 0;}
h1, h2, h3 {color: var(--g-color-text-primary);}
#root {min-height: 100vh;}
.g-root {font-size: 13px;}
.app-shell {
  --gn-aside-header-background-color: var(--g-color-base-generic-ultralight);
  --gn-aside-header-item-current-background-color: var(--g-color-base-selection);
  --gn-aside-header-item-current-background-color-hover: var(--g-color-base-selection-hover);
  --gn-aside-header-item-current-text-color: var(--g-color-text-brand-heavy);
  --gn-aside-header-item-current-icon-color: var(--g-color-text-brand);
