  height: 100vh;
}
.app-logo {font-weight: 750; letter-spacing: -1.1px; color: var(--g-color-text-brand-heavy); margin-bottom: var(--g-spacing-6);}
.workspace-item {margin: var(--g-spacing-4) var(--g-spacing-4) var(--g-spacing-5); width: calc(100% - var(--g-spacing-8)); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-m); background: var(--g-color-base-background); height: 59px;}
.workspace-name {display: flex; align-items: center; gap: var(--g-spacing-3); width: 100%; font-weight: 600;}
.workspace-name > span:nth-child(2) {flex: 1; min-width: 0;}
