.nav-count {font-size: 11px; background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xs); padding: 0 var(--g-spacing-2); line-height: 19px; color: var(--g-color-text-secondary);}
.sidebar-footer {padding: var(--g-spacing-4);}
.sidebar-promo {padding: var(--g-spacing-4); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); margin-bottom: var(--g-spacing-5); position: relative; overflow: hidden; background: var(--g-color-base-background);}
.promo-spark {font-size: 31px; color: var(--g-color-text-brand); line-height: 1; display: block; margin-bottom: var(--g-spacing-3);}
