.sidebar-promo p {font-size: 11px; color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-3); position: relative;}
.promo-link {font-size: 10px; display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-brand);}
