.help-button {width: 100%; margin-bottom: var(--g-spacing-4); color: var(--g-color-text-complementary); font-size: 11px; --g-button-padding: var(--g-spacing-1);}
.theme-toggle {background: var(--g-color-base-generic); border-radius: var(--g-border-radius-m); display: flex; padding: var(--g-spacing-1); gap: var(--g-spacing-1);}
.theme-toggle > button {flex: 1; min-width: 0; font-size: 11px; --g-button-border-radius: var(--g-border-radius-s); --g-button-padding: var(--g-spacing-2);}
.profile-button {width: 100%; height: 62px; margin-top: var(--g-spacing-5); padding: var(--g-spacing-2) 0; border-top: 1px solid var(--g-color-line-generic); --g-button-border-radius: 0; --g-button-padding: 0;}
.profile-avatar, .topbar-avatar {width: 32px; height: 32px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; background: var(--g-color-base-selection); color: var(--g-color-text-brand-heavy); font-size: 10px; font-weight: 650; flex-shrink: 0;}
.profile-text {display: inline-flex; flex-direction: column; align-items: flex-start; gap: var(--g-spacing-1); font-size: 11px; margin: 0 var(--g-spacing-2); max-width: 133px; overflow: hidden; text-overflow: ellipsis;}
.profile-text small {font-size: 9px; font-weight: 400; color: var(--g-color-text-secondary);}
.main-layout {height: 100vh; overflow-y: auto; overflow-x: clip; background: var(--g-color-base-background);}
.topbar {height: 74px; border-bottom: 1px solid var(--g-color-line-generic); padding: 0 var(--g-spacing-10); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-5);}
.breadcrumbs {display: flex; gap: var(--g-spacing-4); color: var(--g-color-text-secondary); align-items: center; font-size: 11px;}
.breadcrumbs > span:last-child {color: var(--g-color-text-primary);}
.breadcrumb-divider {color: var(--g-color-line-generic);}
.topbar-date {color: var(--g-color-text-secondary); display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 11px; white-space: nowrap;}
.topbar-avatar {width: 29px; height: 29px; background: var(--g-color-base-warning-light); color: var(--g-color-text-warning-heavy);}
.notification-button {position: relative; color: var(--g-color-text-complementary);}
.notification-dot {width: 4px; height: 4px; background: var(--g-color-base-brand); position: absolute; right: 9px; top: 5px; border-radius: 50%;}
.main-content {padding: var(--g-spacing-9) var(--g-spacing-10) var(--g-spacing-5); max-width: 1440px; margin: 0 auto; animation: enter .3s ease both;}
.page-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-5); margin-bottom: var(--g-spacing-6);}
.page-heading h1 {margin: var(--g-spacing-2) 0; font-weight: 650; letter-spacing: -.9px;}
.page-heading p {margin-bottom: 0; color: var(--g-color-text-secondary); font-size: 12px;}
