.eyebrow {color: var(--g-color-text-secondary); font-size: 9px; font-weight: 600; letter-spacing: 1.5px;}
.welcome-banner {background: var(--g-color-base-selection); border-radius: var(--g-border-radius-xl); display: grid; grid-template-columns: 1.15fr 1fr; min-height: 263px; position: relative; overflow: hidden;}
.welcome-copy {padding: var(--g-spacing-7) var(--g-spacing-8); position: relative; z-index: 2;}
.welcome-tag {font-size: 8px; color: var(--g-color-text-brand-heavy); letter-spacing: 1.2px; font-weight: 600; display: flex; align-items: center; gap: var(--g-spacing-2); margin-bottom: var(--g-spacing-4);}
.sun-dot {height: 6px; width: 6px; border-radius: 50%; background: var(--g-color-text-brand);}
.welcome-copy h2 {font-size: var(--g-text-display-2-font-size); line-height: 1.18; letter-spacing: -.8px; font-weight: 550; color: var(--g-color-text-brand-heavy); margin-bottom: var(--g-spacing-3);}
.welcome-copy p {font-size: 11px; color: var(--g-color-text-brand-heavy); opacity: .75; margin-bottom: var(--g-spacing-4);}
.hero-button {background: var(--g-color-base-background); --g-button-text-color: var(--g-color-text-brand-heavy); --g-button-background-color: var(--g-color-base-background); --g-button-background-color-hover: var(--g-color-base-generic-ultralight); --g-button-border-radius: var(--g-border-radius-m); font-size: 11px; box-shadow: 0 2px 3px var(--g-color-sfx-shadow);}
.hero-art {position: relative; min-width: 0;}
.orbit {position: absolute; width: 335px; height: 335px; left: 40%; top: 50%; transform: translate(-50%, -50%); border: 1px solid var(--g-color-line-brand); opacity: .13; border-radius: 50%;}
.orbit-two {width: 440px; height: 440px;}
.orbit-three {width: 550px; height: 550px;}
.floating-card {position: absolute; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background); box-shadow: 0 10px 28px var(--g-color-sfx-shadow);}
.back-card {width: 160px; height: 177px; top: 29px; left: 28%; transform: rotate(12deg); padding: var(--g-spacing-5); background: var(--g-color-base-generic-ultralight);}
.art-mini-icon {color: var(--g-color-text-brand); margin-bottom: var(--g-spacing-4);}
.art-line {height: 5px; background: var(--g-color-base-generic-medium); border-radius: var(--g-border-radius-m); margin: var(--g-spacing-3) 0; width: 80%;}
.art-line.long {width: 95%;}.art-line.short {width: 55%;}
.front-card {width: 214px; height: 183px; left: 12%; top: 78px; transform: rotate(-9deg); padding: var(--g-spacing-5);}
.art-check {display: grid; place-items: center; width: 43px; height: 43px; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand); margin-bottom: var(--g-spacing-3);}
.art-card-title {display: block; font-weight: 600; font-size: 13px; margin-bottom: var(--g-spacing-1);}.art-card-subtitle {font-size: 8px; color: var(--g-color-text-secondary);}
.art-progress {height: 5px; background: var(--g-color-base-generic); border-radius: var(--g-border-radius-xs); margin: var(--g-spacing-4) 0 var(--g-spacing-3);}.art-progress > span {display: block; width: 77%; height: 100%; background: var(--g-color-base-brand); border-radius: inherit;}
.art-card-bottom {display: flex; align-items: center; justify-content: space-between; font-size: 7px; color: var(--g-color-text-secondary);}
.mini-faces {display: flex; padding-left: var(--g-spacing-1);}.mini-faces i {width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--g-color-base-background); background: var(--g-color-base-warning-medium); color: var(--g-color-text-primary); font-style: normal; display: grid; place-items: center; margin-left: -4px;}.mini-faces i:nth-child(2) {background: var(--g-color-base-utility-medium);}.mini-faces i:nth-child(3) {background: var(--g-color-base-positive-medium);}
.art-star {position: absolute; color: var(--g-color-text-brand); font-size: 48px; font-weight: 300;}.star-one {right: 15%; top: 34px; transform: rotate(12deg);}.star-two {left: 3%; top: 27px; font-size: 25px;}.art-dot {position: absolute; width: 8px; height: 8px; border-radius: 50%; background: var(--g-color-base-brand);}.dot-one {right: 17%; bottom: 46px; width: 6px; height: 6px;}.dot-two {left: 4%; bottom: 32px; background: var(--g-color-base-warning-heavy);}
.stats-grid {display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--g-spacing-4); padding: var(--g-spacing-7) 0; border-bottom: 1px solid var(--g-color-line-generic); margin-bottom: var(--g-spacing-7);}
.stat-item {display: flex; align-items: center; gap: var(--g-spacing-3); min-width: 0; padding-right: var(--g-spacing-3); border-right: 1px solid var(--g-color-line-generic);}.stat-item:last-child {border-right: 0;}.stat-icon {display: grid; place-items: center; background: var(--g-color-base-generic-ultralight); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-m); width: 40px; height: 40px; flex-shrink: 0; color: var(--g-color-text-complementary);}
.stat-label {display: block; font-size: 10px; color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-2);}.stat-number {font-size: 26px; font-weight: 600; line-height: 1; letter-spacing: -.5px; display: flex; gap: var(--g-spacing-3); align-items: baseline;}.stat-change, .stat-note {font-size: 9px; color: var(--g-color-text-secondary); font-weight: 400; letter-spacing: 0;}.stat-change {color: var(--g-color-text-brand); white-space: nowrap;}.stat-change svg {vertical-align: middle;}
.section-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); margin-bottom: var(--g-spacing-5);}.section-heading h2 {font-size: 17px; font-weight: 600; margin-bottom: 0; letter-spacing: -.3px;}.section-heading > button {font-size: 11px; color: var(--g-color-text-complementary);}.count-badge {background: var(--g-color-base-generic); color: var(--g-color-text-secondary); font-size: 10px; padding: var(--g-spacing-half) var(--g-spacing-2); border-radius: var(--g-border-radius-s);}
.project-grid {display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--g-spacing-4);}.project-card {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5); min-width: 0; transition: border-color .2s, transform .2s, box-shadow .2s; background: var(--g-color-base-background);}.project-card:hover {border-color: var(--g-color-line-brand); transform: translateY(-3px); box-shadow: 0 6px 16px var(--g-color-sfx-shadow);}
