  const [tasks, setTasks] = useState(() => readStored('potok-tasks', initialTasks));
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [sort, setSort] = useState('recent');
  const [modal, setModal] = useState<'new' | 'notifications' | 'help' | null>(null);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [newName, setNewName] = useState('');
  const [newDescription, setNewDescription] = useState('');
  const [newCategory, setNewCategory] = useState(['Дизайн']);
  const [profile, setProfile] = useState(() => readStored('potok-profile', {name: 'Александр Ковалёв', email: 'alex@studio.design', workspace: 'Студия', notifications: true, digest: false}));
  const [notice, setNotice] = useState('');
  useEffect(() => {const handler = () => setPage(getPage()); const resize = () => setNarrow(window.innerWidth < 760); window.addEventListener('hashchange', handler); window.addEventListener('resize', resize); return () => {window.removeEventListener('hashchange', handler); window.removeEventListener('resize', resize);};}, []);
  useEffect(() => {localStorage.setItem('potok-theme', JSON.stringify(theme)); document.documentElement.style.colorScheme = theme;}, [theme]);
  useEffect(() => {localStorage.setItem('potok-projects', JSON.stringify(projects));}, [projects]);
  useEffect(() => {localStorage.setItem('potok-tasks', JSON.stringify(tasks));}, [tasks]);
  useEffect(() => {if (notice) {const timer = setTimeout(() => setNotice(''), 3500); return () => clearTimeout(timer);}}, [notice]);
  const navigate = (next: Page) => {window.location.hash = next; setPage(next); setSearch('');};
  const createProject = (e: FormEvent) => {e.preventDefault(); if ("'!newName.trim()) return; setProjects(current => [{id: Date.now(), name: newName.trim(), description: newDescription.trim() || '"'Здесь начинается что-то хорошее', category: newCategory[0], color: ['violet', 'peach', 'green'][current.length % 3], progress: 0, tasks: 0, done: 0, date: 'Без срока', status: 'В работе', members: ['АК']}, ...current]); setModal(null); setNewName(''); setNewDescription(''); navigate('projects'); setFilter('all'); setNotice('Проект создан. Время воплощать идеи"'!'"');};
  const openNew = () => {setNewName(''); setNewDescription(''); setModal('new');};
  const filteredProjects = projects.filter(p => "'`${p.name} ${p.description} ${p.category}`.toLowerCase().includes(search.toLowerCase()) && (filter === '"'all' || (filter === 'active' && p.status === 'В работе') || (filter === 'review' && p.status === 'На проверке') || (filter === 'completed' && p.status === 'Завершён'))).sort((a, b) => sort === 'name' ? a.name.localeCompare(b.name, 'ru') : sort === 'progress' ? b.progress - a.progress : 0);
  const completed = tasks.filter(t => t.done).length;

