    <section className=\"projects-section\"><div className=\"section-heading\"><Flex alignItems=\"center\" gap={3}><Text as=\"h2\" variant=\"header-1\">Мои проекты</Text><span className=\"count-badge\">{projects.length}</span></Flex><Button view=\"flat\" onClick={() => navigate('projects')}>Все проекты <Icon data={ArrowRight} size={15}/></Button></div><div className=\"project-grid\">{projects.slice(0, 3).map(p => <ProjectCard key={p.id} project={p}/>)}</div></section>
    <div className=\"bottom-grid\"><section className=\"task-panel\"><div className=\"section-heading\"><Flex alignItems=\"center\" gap={3}><Text as=\"h2\" variant=\"header-1\">В фокусе сегодня</Text><span className=\"count-badge\">{tasks.length - completed}</span></Flex><span className=\"muted small\">4 ноября</span></div><div className=\"task-list\">{tasks.map(task => <div className={"'`task-row ${task.done ? '"'is-done' : ''}"'`} key={task.id}><Checkbox size="l" checked={task.done} onUpdate={done => setTasks(ts => ts.map(t => t.id === task.id ? {...t, done} : t))} controlProps={{'"'aria-label': task.title}}/><div className=\"task-copy\"><span className=\"task-title\">{task.title}</span><span className=\"task-project\"><i className={task.color}/>{task.project}</span></div><span className=\"task-date\">{task.done ? <Icon data={Check} size={15}/> : task.time}</span></div>)}</div><div className=\"task-panel-bottom\"><span>{completed} из {tasks.length} задач выполнено</span><span>Хороший темп <span className=\"tiny-spark\">✧</span></span></div></section>
    <section className=\"activity-panel\"><div className=\"section-heading\"><Text as=\"h2\" variant=\"header-1\">Пульс команды</Text><span className=\"live-dot\"/></div><div className=\"activity-row\"><span className=\"activity-avatar violet\">МС</span><div><p><strong>Мария</strong> обновила макеты</p><span>Редизайн сайта <b>·</b> 20 мин назад</span></div></div><div className=\"activity-row\"><span className=\"activity-avatar peach\">ДВ</span><div><p><strong>Дмитрий</strong> выполнил 3 задачи</p><span>Мобильное приложение <b>·</b> 1 ч назад</span></div></div><div className=\"activity-row\"><span className=\"activity-avatar green\">ЕЛ</span><div><p><strong>Елена</strong> добавила комментарий</p><span>Бренд-платформа <b>·</b> 2 ч назад</span></div></div><span className=\"team-note\">Маленькие победы. Большое движение.</span></section></div>
    <footer className=\"page-footer\"><span>Поток — пространство для ваших идей.</span><span>Сделано для спокойной работы <span>✳</span></span></footer>
  </>;

  return <ThemeProvider theme={theme} lang=\"ru\"><AsideHeader className=\"app-shell\" compact={narrow} hideCollapseButton headerDecoration={false}
