    subheaderItems={narrow ? [] : [{item: {id: 'workspace', title: <span className=\"workspace-name\"><span className=\"workspace-letter\">С</span><span>{profile.workspace}<small>Рабочее пространство</small></span><Icon data={ChevronDown} size={14}/></span>, onItemClick: () => navigate('settings'), className: 'workspace-item'}}]}
    menuItems={([{id: 'overview', title: 'Обзор', icon: House}, {id: 'projects', title: 'Проекты', icon: Folder, rightAdornment: <span className=\"nav-count\">{projects.length}</span>}, {id: 'settings', title: 'Настройки', icon: Gear}] as const).map(item => ({...item, current: page === item.id, onItemClick: () => navigate(item.id), className: 'app-nav-item', tooltipText: item.title}))}
    renderFooter={() => <div className={"'`sidebar-footer ${narrow ? '"'compact-footer' : ''}"'`}>{!narrow && <><div className="sidebar-promo"><span className="promo-spark">✧</span><Text as="h3" variant="subheader-2">Место для большего</Text><p>От идеи до результата.<br/>В вашем собственном ритме.</p><span className="promo-link">Поймайте свой поток <Icon data={ArrowUpRight} size={14}/></span><span className="promo-orbit"/></div><Button view="flat" className="help-button" onClick={() => setModal('"'help')}><Icon data={CircleQuestion} size={18}/> Помощь и поддержка <Icon data={ArrowUpRight} size={13}/></Button><div className=\"theme-toggle\" aria-label=\"Тема оформления\"><Button view={theme === 'light' ? 'raised' : 'flat'} selected={theme === 'light'} onClick={() => setTheme('light')}><Icon data={Sun} size={16}/> Светлая</Button><Button view={theme === 'dark' ? 'raised' : 'flat'} selected={theme === 'dark'} onClick={() => setTheme('dark')}><Icon data={Moon} size={15}/> Тёмная</Button></div></>}{narrow && <Button view=\"flat\" aria-label=\"Переключить тему\" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}><Icon data={theme === 'light' ? Moon : Sun} size={19}/></Button>}<Button view=\"flat\" className=\"profile-button\" onClick={() => navigate('settings')} aria-label=\"Настройки профиля\"><span className=\"profile-avatar\">АК</span>{"'!narrow && <><span className="profile-text">{profile.name}<small>Личное пространство</small></span><Icon data={ChevronDown} size={13}/></>}</Button></div>}
    renderContent={() => <div className="main-layout"><header className="topbar"><div className="breadcrumbs"><span>{narrow ? '"'Поток' : 'Рабочее пространство'}</span><span className=\"breadcrumb-divider\">/</span><span>{pageNames[page]}</span></div><Flex alignItems=\"center\" gap={4}><span className=\"topbar-date\"><Icon data={Calendar} size={15}/> Среда, 4 ноября</span><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={() => setModal('notifications')}><Icon data={Bell} size={19}/><span className=\"notification-dot\"/></Button><span className=\"topbar-avatar\">АК</span></Flex></header><main className=\"main-content\" key={page}>
      {page === 'overview' && renderOverview()}
      {page === 'projects' && <><div className=\"page-heading\"><div><div className=\"eyebrow\">ОТ ИДЕИ К РЕЗУЛЬТАТУ</div><Text as=\"h1\" variant=\"display-2\">Проекты</Text><p>Всё, над чем вы работаете. Всё, что вас вдохновляет.</p></div><Button view=\"action\" size=\"l\" onClick={openNew}><Icon data={Plus} size={17}/> Создать проект</Button></div><div className=\"projects-toolbar\"><div className=\"filter-tabs\">{[['all', 'Все проекты'], ['active', 'В работе'], ['review', 'На проверке'], ['completed', 'Завершённые']].map(([value, label]) => <Button key={value} view={filter === value ? 'normal' : 'flat'} selected={filter === value} onClick={() => setFilter(value)}>{label}{value === 'all' && <span className=\"tab-count\">{projects.length}</span>}</Button>)}</div><Select value={[sort]} onUpdate={v => setSort(v[0])} options={[{value: 'recent', content: 'Сначала новые'}, {value: 'name', content: 'По названию'}, {value: 'progress', content: 'По прогрессу'}]} aria-label=\"Сортировка проектов\"/></div><div className=\"search-row\"><TextInput placeholder=\"Найти проект…\" value={search} onUpdate={setSearch} startContent={<Icon data={Magnifier} size={17}/>} hasClear size=\"l\" controlProps={{'aria-label': 'Поиск проектов'}}/><span className=\"muted\">{filteredProjects.length} проектов</span></div>{filteredProjects.length > 0 ? <div className=\"project-grid all-projects\">{filteredProjects.map(p => <ProjectCard key={p.id} project={p}/>)}</div> : <div className=\"empty-state\"><span className=\"empty-icon\"><Icon data={search ? Magnifier : Folder} size={36}/></span><Text as=\"h2\" variant=\"header-1\">{search ? 'Ничего не нашлось' : 'Пока здесь тихо'}</Text><p>{search ? 'Попробуйте другое название или сбросьте фильтры.' : 'Проекты с этим статусом появятся здесь.'}</p><Button view=\"outlined\" onClick={() => {setSearch(''); setFilter('all');}}>Показать все проекты</Button></div>}<div className=\"projects-tip\"><Icon data={Sparkles} size={20}/><span>У каждой большой идеи есть первый шаг. Создайте проект и сделайте его сегодня.</span></div></>}
      {page === 'settings' && <><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ ПОТОК, ВАШИ ПРАВИЛА</div><Text as=\"h1\" variant=\"display-2\">Настройки</Text><p>Пусть рабочее пространство подстраивается под вас.</p></div></div><form className=\"settings-form\" onSubmit={e => {e.preventDefault(); localStorage.setItem('potok-profile', JSON.stringify(profile)); setNotice('Настройки сохранены');}}><section className=\"settings-section\"><span className=\"settings-section-icon\"><Icon data={PersonIcon} size={21}/></span><div className=\"settings-section-body\"><Text as=\"h2\" variant=\"header-1\">Ваш профиль</Text><p className=\"muted\">Так вас видят участники команды.</p><div className=\"form-grid\"><label>Имя и фамилия<TextInput size=\"l\" value={profile.name} onUpdate={name => setProfile({...profile, name})} controlProps={{required: true}}/></label><label>Электронная почта<TextInput size=\"l\" type=\"email\" value={profile.email} onUpdate={email => setProfile({...profile, email})} controlProps={{required: true}}/></label></div><label className=\"workspace-field\">Название рабочего пространства<TextInput size=\"l\" value={profile.workspace} onUpdate={workspace => setProfile({...profile, workspace})} controlProps={{required: true}}/></label></div></section><section className=\"settings-section\"><span className=\"settings-section-icon\"><Icon data={Sun} size={21}/></span><div className=\"settings-section-body\"><Text as=\"h2\" variant=\"header-1\">Оформление</Text><p className=\"muted\">Выберите настроение для своей работы. Тема сохраняется автоматически.</p><div className=\"theme-options\">{(['light', 'dark'] as const).map(t => <Button key={t} view=\"outlined\" className={"'`theme-option ${theme === t ? '"'active' : ''}"'`} onClick={() => setTheme(t)}><Icon data={t === '"'light' ? Sun : Moon} size={23}/><span>{t === 'light' ? 'Светлая тема' : 'Тёмная тема'}</span>{theme === t && <Icon data={CircleCheck} size={18}/>}</Button>)}</div></div></section><section className=\"settings-section\"><span className=\"settings-section-icon\"><Icon data={Bell} size={21}/></span><div className=\"settings-section-body\"><Text as=\"h2\" variant=\"header-1\">Уведомления</Text><p className=\"muted\">Только то, что помогает оставаться в курсе.</p><div className=\"setting-switch-row\"><div><strong>Обновления проектов</strong><p className=\"muted\">Новые комментарии и изменения статусов.</p></div><Switch checked={profile.notifications} onUpdate={notifications => setProfile({...profile, notifications})} controlProps={{'aria-label': 'Обновления проектов'}}/></div><div className=\"setting-switch-row\"><div><strong>Итоги недели</strong><p className=\"muted\">Короткое письмо о вашем прогрессе каждую пятницу.</p></div><Switch checked={profile.digest} onUpdate={digest => setProfile({...profile, digest})} controlProps={{'aria-label': 'Итоги недели'}}/></div></div></section><div className=\"settings-actions\"><span className=\"muted\">Всё готово? Сохраните изменения.</span><Button view=\"action\" size=\"l\" type=\"submit\">Сохранить изменения <Icon data={Check} size={16}/></Button></div></form></>}
